package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_Timer_TriageGen2Test {

    @Test
    public void testConstructorAndIsCountingInitialState() {
        // Test the constructor with a specific duration
        long duration = 1000L;
        Timer timer = new Timer(duration);

        // Verify that the object is created and isCounting returns false initially
        // (Assuming isCounting() returns false before start() is called)
        assertFalse("Timer should not be counting before start() is called", timer.isCounting());
    }

    @Test
    public void testStartChangesCountingState() {
        // Test the lifecycle: Constructor -> start() -> isCounting()
        long duration = 500L;
        Timer timer = new Timer(duration);

        assertFalse("Timer should not be counting initially", timer.isCounting());

        timer.start();

        assertTrue("Timer should be counting after start() is called", timer.isCounting());
    }

    @Test
    public void testConstructorWithZeroDuration() {
        // Test boundary condition: zero duration
        Timer timer = new Timer(0L);
        assertFalse("Timer with zero duration should still be initialized", timer.isCounting());
        timer.start();
        assertTrue("Timer with zero duration should be counting after start", timer.isCounting());
    }

    @Test
    public void testConstructorWithNegativeDuration() {
        // Test boundary condition: negative duration
        Timer timer = new Timer(-1L);
        assertFalse("Timer with negative duration should still be initialized", timer.isCounting());
        timer.start();
        assertTrue("Timer with negative duration should be counting after start", timer.isCounting());
    }
}
